changeSet.sql:
DO $$
BEGIN
    IF (SELECT count(*) FROM tag) > 0 OR (SELECT count(*) FROM note_tag) > 0 THEN
        RAISE EXCEPTION 'migration 020 expects zero tag/note_tag rows (found tag=%, note_tag=%); tag data would be lost',
            (SELECT count(*) FROM tag), (SELECT count(*) FROM note_tag);
    END IF;
END $$;

-- Drop the migration scoping.
ALTER TABLE tag DROP CONSTRAINT IF EXISTS uq_tag_name_migration;
ALTER TABLE tag DROP CONSTRAINT IF EXISTS fk_tag_migration;
DROP INDEX IF EXISTS idx_tag_migration;
ALTER TABLE tag DROP COLUMN IF EXISTS migration_id;

-- A tag now belongs to a user. NOT NULL: every tag has an owner.
ALTER TABLE tag ADD COLUMN user_id VARCHAR(255) NOT NULL
    REFERENCES "user"(username) ON DELETE CASCADE;

-- One namespace per user: "idea" is a single row per owner.
ALTER TABLE tag ADD CONSTRAINT uq_tag_name_user UNIQUE (user_id, tag_name);
CREATE INDEX idx_tag_user ON tag(user_id);
